cd /tmp/an && cat > spell39.py <<'PYEOF'
import json, sys
from pathlib import Path
sys.path.insert(0,'/workspace/harness/solver')
from answer_conventions import final_answer_field, MARKUP, split_items
base=Path('/workspace/runs/4383c6264deaf3410877e957b8f891f1f3da2936/LawBench')
def text_of(m):
    c=m.get('content')
    if isinstance(c,list): return ''.join(x.get('text','') for x in c if isinstance(x,dict))
    return c or ''
def norm(a): return MARKUP.sub('', (a or '')).strip()
def iset(a): return set(split_items(norm(a)))
n=0
for d in sorted((base/'conversations').iterdir()):
    if d.name=='prepare' or not d.is_dir(): continue
    for f in sorted(d.glob('sample-*.json')):
        t=json.loads(f.read_text())
        if t.get('status')!='ok': continue
        first=None
        for m in t['messages']:
            if m.get('role')=='assistant':
                fa=final_answer_field(text_of(m))
                if fa: first=fa; break
        if first is None: continue
        if iset(first)==iset(t['target']) and norm(first)!=t['target']:
            n+=1
            print(f"ex{t['example_index']}.{t['sample_index']} correct={t.get('was_correct')} first={norm(first)!r} final={norm(t['prediction'])!r} target={t['target']!r}")
print('total', n)
PYEOF
