import json
from pathlib import Path
from collections import Counter
base=Path('/workspace/runs/4383c6264deaf3410877e957b8f891f1f3da2936/LawBench')
rows={}
for d in sorted((base/'conversations').iterdir()):
    if d.name=='prepare' or not d.is_dir(): continue
    for f in sorted(d.glob('sample-*.json')):
        t=json.loads(f.read_text())
        if t.get('status')!='ok': continue
        rows.setdefault(t['example_index'],[t['target'],[]])[1].append(bool(t.get('was_correct')))
def ncharges(a):
    for s in (';','；'):
        if s in a: return len([x for x in a.split(s) if x.strip()])
    return 1
single=[(i,t,c) for i,(t,c) in rows.items() if ncharges(t)==1]
multi=[(i,t,c) for i,(t,c) in rows.items() if ncharges(t)>1]
print('single-charge val examples:', len(single), 'samples', sum(len(c) for _,_,c in single), 'correct', sum(sum(c) for _,_,c in single))
print('multi-charge val examples:', len(multi), 'samples', sum(len(c) for _,_,c in multi), 'correct', sum(sum(c) for _,_,c in multi))
print()
for i,t,c in multi: print(f'  ex{i} {sum(c)}/{len(c)} {t[:80]}')
